SELECT id, stocks_id, stocks_shortname, bar_start_time, reference_price, ma1d, ma7d, ma30d, zscore1d, zscore7d, zscore30d, return6h, return1d, return7d, return14d, low30d, high30d, width30d, position30, pct_above_30d_low, pct_below_30d_high, strategy_ready, data_quality_reason, feature_version, deleted, create_time, update_time FROM torn_stock_strategy_feature_15m WHERE bar_start_time >= #{startTime} AND bar_start_time <= #{endTime} AND feature_version = #{featureVersion} AND stocks_id IN
#{id}
AND deleted = 0 ORDER BY stocks_id ASC, bar_start_time ASC, id ASC
